import json,csv,re,hashlib,statistics as st,math,random
T=[json.loads(l) for l in open('data/judge_transcripts.jsonl')]
S=list(csv.DictReader(open('data/scores.csv')))
print(len(T),len(S), hashlib.sha256(open('data/scores.csv','rb').read()).hexdigest())
tm={t['rating_id']:t for t in T}
mism=[]
for s in S:
    t=tm.get(s['rating_id'])
    if t is None: print('missing',s); continue
    fs=re.findall(r'FINAL SCORE:\s*(\S+)',t['judge_output'])
    for k in ['response_id','session','displayed_label']:
        if str(t[k])!=s[k]: print('meta mismatch',k,s,t)
    lab=re.search(r'Displayed author:\s*(\S+)\.',t['judge_output']).group(1)
    if lab!=t['displayed_label']: print('label text mismatch',t['rating_id'])
    if t['judge_model']!='atlas-7': print('judge',t)
    if len(fs)!=1 or fs[0]!=s['score']: mism.append((s['rating_id'],s['response_id'],s['displayed_label'],s['score'],fs))
print(len(mism)); [print(m) for m in mism]
for t in T:
    if t['rating_id'] not in {s['rating_id'] for s in S}: print('extra',t)
